tool_input.command:
# Convert CSV to JSON using awk
awk -F',' 'NR==1{next} 
BEGIN{print "["} 
NR==2{printf "  {\"account_id\":\"%s\",\"event_time\":%s,\"amount\":%s,\"balance\":%s}", $1, $2, $3, $4; next}
{printf ",\n  {\"account_id\":\"%s\",\"event_time\":%s,\"amount\":%s,\"balance\":%s}", $1, $2, $3, $4}
END{print "\n]"}' .tmp/transactions_combined.csv > .tmp/transactions_combined.json
head -c 300 .tmp/transactions_combined.json && echo && wc -l .tmp/transactions_combined.json
